//! The app icon (`assets/app-icon/`, regenerated by `packaging/icons.sh`).
//!
//! - **Executable:** `apps/guitario/build.rs` embeds `guitario.ico` (16–256 px) on Windows.
//! - **Window:** [`window_icon`] sets the title-bar and taskbar icon at run time (the Dock when
//!   running unbundled on macOS).
//! - **Homepage:** [`mark`] is the line work alone, tinted with the theme's text colour.

/// Window, taskbar and (unbundled) Dock icon: macOS gets the padded 1024 px render on Apple's icon
/// grid; elsewhere the tighter 256 px render reads better at small sizes.
pub fn window_icon() -> egui::IconData {
    eframe::icon_data::from_png_bytes(WINDOW).unwrap_or_default()
}

#[cfg(target_os = "macos")]
const WINDOW: &[u8] = include_bytes!("../../../assets/app-icon/guitario-1024.png");
#[cfg(not(target_os = "macos"))]
const WINDOW: &[u8] = include_bytes!("../../../assets/app-icon/hicolor/256x256/apps/ai.storyteller.guitario.png");

/// The mark without its tile: white line work on transparent, 192 px.
const MARK: &[u8] = include_bytes!("../../../assets/app-icon/guitario-mark.png");

/// The mark as a texture, loaded once per context; `None` if it cannot be decoded.
pub(crate) fn mark(ctx: &egui::Context) -> Option<egui::TextureHandle> {
    let id = egui::Id::new("guitario-mark");
    if let Some(t) = ctx.data(|d| d.get_temp::<egui::TextureHandle>(id)) {
        return Some(t);
    }
    let icon = eframe::icon_data::from_png_bytes(MARK).ok()?;
    let size = [usize::try_from(icon.width).ok()?, usize::try_from(icon.height).ok()?];
    let image = egui::ColorImage::from_rgba_unmultiplied(size, &icon.rgba);
    let tex = ctx.load_texture("guitario-mark", image, egui::TextureOptions::LINEAR);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

#[cfg(test)]
mod tests {
    #![allow(clippy::indexing_slicing, clippy::expect_used)]
    use super::*;

    const ICO: &[u8] = include_bytes!("../../../assets/app-icon/guitario.ico");

    fn u16_at(b: &[u8], i: usize) -> usize {
        u16::from_le_bytes([b[i], b[i + 1]]) as usize
    }
    fn u32_at(b: &[u8], i: usize) -> usize {
        u32::from_le_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]]) as usize
    }

    #[test]
    fn the_window_icon_and_the_mark_decode() {
        let icon = window_icon();
        assert!(icon.width >= 256 && icon.width == icon.height, "{}x{}", icon.width, icon.height);
        assert_eq!(icon.rgba.len(), icon.width as usize * icon.height as usize * 4);
        assert!(icon.rgba.chunks(4).any(|p| p[3] > 0), "the icon isn't blank");
        let ctx = egui::Context::default();
        let tex = mark(&ctx).expect("the mark decodes");
        assert_eq!(tex.size(), [192, 192]);
        assert_eq!(mark(&ctx).map(|t| t.id()), Some(tex.id()), "loaded once");
    }

    /// The `.ico` build.rs embeds: every size Windows asks for, each a PNG of that size.
    #[test]
    fn the_exe_icon_has_every_shell_size() {
        assert_eq!((u16_at(ICO, 0), u16_at(ICO, 2)), (0, 1), "ICONDIR header, type 1 (icon)");
        let mut sizes = Vec::new();
        for i in 0..u16_at(ICO, 4) {
            let e = 6 + i * 16;
            let w = if ICO[e] == 0 { 256 } else { ICO[e] as usize };
            let (len, off) = (u32_at(ICO, e + 8), u32_at(ICO, e + 12));
            let data = ICO.get(off..off + len).expect("image data inside the file");
            assert!(data.starts_with(b"\x89PNG\r\n\x1a\n"), "{w}px entry is not a PNG");
            let pw = u32::from_be_bytes([data[16], data[17], data[18], data[19]]) as usize;
            assert_eq!(pw, w, "{w}px entry holds a {pw}px PNG");
            sizes.push(w);
        }
        for want in [16, 24, 32, 48, 64, 256] {
            assert!(sizes.contains(&want), "guitario.ico lacks {want}px (has {sizes:?})");
        }
    }
}
